PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE studentscsv (
    student_firstname TEXT,
    student_surname TEXT,
    student_id TEXT,
    student_email TEXT,
    year INTEGER,
    address TEXT,
    contact_number TEXT,
    module_id TEXT,
    module_name TEXT,
    leader TEXT,
    lecturer1 TEXT,
    lecturer2 TEXT,
    exam_mark REAL,
    coursework1 REAL,
    coursework2 REAL,
    coursework3 REAL
);
CREATE TABLE facultiescsv (
    faculty TEXT,
    building TEXT,
    room TEXT,
    capacity INTEGER,
    lecturer_email TEXT,
    lecturer_firstname TEXT,
    lecturer_surname TEXT
);
COMMIT;
